function currentArenas(){return turnBased?[arenas[activeTurn]]:arenas;}
function setPause(v){if(!started||finished||isPaused===v)return;if(v){isPaused=true;pausedAt=performance.now();pointers.clear();for(let a of arenas){a.drags.clear();a.launch=null;}overlay.hidden=false;overlay.innerHTML='<div class="result-card"><span class="eyebrow">PAUSED</span><h2>A little breather.</h2><p>Your adventure is waiting right here.</p><button class="btn primary" id="arenaResume">KEEP PLAYING →</button></div>';$('#arenaResume').onclick=()=>setPause(false);}else{pauseMs+=performance.now()-pausedAt;isPaused=false;overlay.hidden=true;}$('#arenaPause').textContent=isPaused?'▶ RESUME':'Ⅱ PAUSE';}
