prompt(){let previous=this.answer;if(!learn){this.promptText='POP THE BALLOONS · WATCH FOR SPIKES';this.answer=null;return;}if(difficulty===1){this.answer=this.pick(Object.keys(colors));this.promptText='FIND '+this.answer.toUpperCase();}else if(difficulty===2){this.answer=Math.floor(this.rand(1,13));this.promptText='FIND NUMBER '+this.answer;}else{let a=Math.floor(this.rand(2,difficulty===5?13:10)),b=Math.floor(this.rand(1,difficulty===5?13:10)),multiply=difficulty>=4&&this.rng()<.5;this.answer=multiply?a*b:a+b;this.promptText=`${a} ${multiply?'×':'+'} ${b} = ?`;}
for(let b of this.items)if(this.isBalloonCorrect(b))b.born=this.clock;}
